import sys
from collections import defaultdict

def main():
    s = sys.stdin.readline().strip()
    n = len(s)
    count = 0
    digits_to_track = [3, 4, 6, 7, 8, 9]
    current_rem = {d: 0 for d in digits_to_track}
    freq = {d: defaultdict(int) for d in digits_to_track}
    for d in digits_to_track:
        freq[d][0] = 1

    for i, char in enumerate(s):
        if char == '0':
            continue
        d = int(char)
        if d in (1, 2, 5):
            count += i + 1
        elif d in digits_to_track:
            current_rem[d] = (current_rem[d] * 10 + d) % d
            count += freq[d][current_rem[d]]
            freq[d][current_rem[d]] += 1
    print(count)

if __name__ == "__main__":
    main()

import sys
from collections import Counter

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print("No")
        return

    n = int(data[0].strip())
    A = list(map(int, data[1].split()))
    B = list(map(int, data[2].split()))

    F_A = [x for x in A if x != -1]
    V_A = len(A) - len(F_A)
    F_B = [x for x in B if x != -1]
    V_B = len(B) - len(F_B)

    if not F_A and not F_B:
        print("Yes")
        return

    max_F = 0
    if F_A:
        max_F = max(max_F, max(F_A))
    if F_B:
        max_F = max(max_F, max(F_B))

    candidates = set()
    for a in F_A:
        for b in F_B:
            candidates.add(a + b)

    if not candidates:
        missing_A = len(F_B)
        if missing_A <= V_A:
            print("Yes")
            return
        else:
            print("No")
            return

    for S in candidates:
        if S < max_F:
            continue

        countA = Counter(F_A)
        missing_A = 0
        for b_val in F_B:
            x = S - b_val
            if countA.get(x, 0) > 0:
                countA[x] -= 1
            else:
                missing_A += 1

        countB = Counter(F_B)
        missing_B = 0
        for a_val in F_A:
            x = S - a_val
            if countB.get(x, 0) > 0:
                countB[x] -= 1
            else:
                missing_B += 1

        if missing_A <= V_A and missing_B <= V_B:
            print("Yes")
            return

    print("No")

if __name__ == '__main__':
    main()

