def main():
    caption = input().strip()
    n = len(caption)

    if n < 3:
        print("")
        return

    min_cost = float('inf')
    best_char = None

    for c in 'abcdefghijklmnopqrstuvwxyz':
        cost = sum(abs(ord(c) - ord(char)) for char in caption)
        if cost < min_cost:
            min_cost = cost
            best_char = c
        elif cost == min_cost and c < best_char:
            best_char = c

    if best_char is None:
        print("")
    else:
        print(best_char * n)

if __name__ == "__main__":
    main()

