import math
from collections import defaultdict

def main(nums, threshold):
    big_nums = [x for x in nums if x > threshold]
    small_nums = [x for x in nums if x <= threshold]
    small_nums_set = set(small_nums)

    if not small_nums:
        return len(big_nums)

    parent = {num: num for num in small_nums}
    rank = {num: 0 for num in small_nums}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    for a in small_nums:
        divisors = []
        i = 1
        while i * i <= a:
            if a % i == 0:
                divisors.append(i)
                if i != a // i:
                    divisors.append(a // i)
            i += 1
        for d in divisors:
            a_prime = a // d
            T = threshold // a
            if a_prime > T:
                continue
            for b_prime in range(a_prime, T + 1):
                if math.gcd(a_prime, b_prime) == 1:
                    b_val = d * b_prime
                    if b_val in small_nums_set and b_val != a:
                        union(a, b_val)

    components = set()
    for num in small_nums:
        components.add(find(num))

    return len(components) + len(big_nums)

if __name__ == "__main__":
